interface PaymentTarget {
    void pay(long amountInCents) throws PaymentFailedException;
}

// Third-party: you cannot edit this. Uses double dollars, returns int codes.
final class VendorGateway {
    int makePayment(double amountInDollars) { /* ... */ return 0; }
}

final class PaymentAdapter implements PaymentTarget {
    private final VendorGateway gateway;

    PaymentAdapter(VendorGateway gateway) {
        this.gateway = gateway;
    }

    @Override
    public void pay(long amountInCents) throws PaymentFailedException {
        if (amountInCents <= 0) throw new PaymentFailedException("non-positive amount");
        // Exact conversion: never new BigDecimal(double). Trade-off: verbosity for correctness.
        java.math.BigDecimal dollars = java.math.BigDecimal.valueOf(amountInCents)
            .movePointLeft(2);
        int code;
        try {
            code = gateway.makePayment(dollars.doubleValue());
        } catch (RuntimeException e) {
            throw new PaymentFailedException("gateway call failed", e);
        }
        // Exhaustive mapping. Unknown codes fail loud, never default to success.
        switch (code) {
            case 0: return;
            case 1: throw new PaymentFailedException("declined");
            case 2: throw new PaymentFailedException("retryable: gateway busy");
            default: throw new PaymentFailedException("unmapped gateway code: " + code);
        }
    }
}

// Client depends only on PaymentTarget. Swap Stripe/Adyen by swapping adapters.
class CheckoutService {
    private final PaymentTarget payments;
    CheckoutService(PaymentTarget payments) { this.payments = payments; }
    void checkout(long totalCents) throws PaymentFailedException {
        payments.pay(totalCents);
    }
}

from abc import ABC, abstractmethod

class Target(ABC):
    @abstractmethod
    def request(self) -> str: ...

class Adaptee:
    def specific_request(self) -> str:
        return ".eetpadA eht fo roivaheb laicepS"

# Object Adapter (prefer): composition, swappable at runtime.
class ObjectAdapter(Target):
    def __init__(self, adaptee: Adaptee) -> None:
        self._adaptee = adaptee
    def request(self) -> str:
        # Translate: reverse the string protocol into ours.
        return self._adaptee.specific_request()[::-1]

# Class Adapter (avoid in most codebases): inheritance, bound at compile time.
# Trade-off: one fewer object, but you cannot wrap an existing instance
# and you inherit every public method of Adaptee whether you want it or not.
class ClassAdapter(Adaptee, Target):
    def request(self) -> str:
        return self.specific_request()[::-1]
